dataModel:
public enum HordeRole { Guard, Build, Roam, Attack, Border }
public sealed class Horde {
  public int Id; public HexCoord Tile; public int Count; public HordeRole Role;
  public int? HiveId, TargetBaseId; public float ProgressHours;
  public Dictionary<string, float> Mix = new(); // "runner" -> 0.15
}
public record HordeSizeDef(string Key, int Min, int Max, int Cost);

public sealed class Hive {
  public int Id; public HexCoord Tile; public float Resources; public int BornDay, Tier;
  public int GuardHordeId; public List<Growth> Growths = new(); public DefenceRead Adapt = new();
}
public sealed class Growth { public string DefId; public HexCoord Tile; public int DaysLeft; public float Flesh; public bool Withered; }
public record GrowthDef(string Id, int Tier, int Cost, int Days, int Max, string? Unlocks, float Income, string ArtKey);
public sealed class HiveSite { public int Id; public HexCoord Tile; public float ScoreIn; public int DeadIn; }

public record ZombieTypeDef(string Id, float Hp, float Dmg, int Aim, float Mob, float Armor,
  float Share, float BreedCost, string Behaviour, string? Counters, int Size = 1, string ArtKey = "");
public interface IZombieBehaviour { bool TryAct(BattleState b, Unit u, Rng rng); }
public sealed class DefenceRead { public float Walls, Trench, Wire, Mines, Light; }
public sealed class Tunnel { public int Id; public GridPos A, B; public int Len; public bool Open; }

public sealed class Den { public int Seed, Rings, CoreId; public int[] MouthIds = new int[4];
  public List<Chamber> Chambers = new(); }
public sealed class Chamber { public int Id, Ring, Index; public string Kind; public Dir Wall;
  public float Warmth, Beat; public bool Cleared, Known; }
public enum CrawlStep { PickMouth, AtChamber, Listening, Fighting, Between, Leaving, Done }
public sealed class CrawlSession { public int HiveId, PartyId, ChamberId; public CrawlStep Step; }

public record DefencePieceDef(string Id, int W, int H, BaseTier Opens, string BattleCell,
  float HoldMult, Dictionary<string, MaterialCost> ByMaterial, string ArtKey);
public sealed class PlacedPiece { public int Id; public string DefId, Material; public GridPos At; public int Rot, Hp; }
public readonly record struct HoldResult(bool Held, float Limit, int Outside, int Inside);
public interface IDefenceResolver { HoldResult HoldCheck(Base b, AttackForce a); }

public enum AttackerKind { Any, Dead, People }
public sealed class DefencePlan { public int Id; public string Name; public AttackerKind Who; public TimeBand When;
  public Dictionary<string, PlanMap> Maps = new(); } // key: "fort" | "wall" | "interior"
public record PlanMap(int W0, int H0, List<Post> Posts);
public record Post(int SurvivorId, int X, int Y, PostRole Role);
public sealed class WatchShift { public string Name; public int From, To; public List<int> Ids = new(); }

public interface IController { void Hour(SimContext ctx, Holdout me); void Day(SimContext ctx, Holdout me); }
public class Holdout { public int Id; public bool IsPlayer; public IController Controller; public string ProfileId;
  public List<int> BaseIds = new(), PeopleIds = new(); public KnowledgeMap Knows = new(); }
public interface IOption { string Domain { get; } ICommand Command { get; } }
public interface IConsideration { string Id { get; } float Score(SimContext c, Holdout me, IOption o); } // 0..1
public record Personality(string Id, Dictionary<string, float> Weights);
public record Decision(string Domain, IOption Chosen, (IOption o, float s)[] Top);

public record GroupTypeDef(string Id, string Label, Attitude Attitude, int Goodwill, float Arms,
  float RaidOdds, string Color, Dictionary<string, float> Weights, string[] Names);
public sealed class Group : Holdout { public string TypeId; public int Goodwill; public float Escalation, Strife; }
public enum LedgerSource { Start, Scavenge, Craft, Trade, Loot, Heal, Consume, Spoil, Lost }
public record LedgerEntry(int HoldoutId, string ItemKey, int Delta, LedgerSource Source, int Hour);

public sealed class RelationsMatrix {
  readonly Dictionary<(int, int), float> _rel = new();
  static (int, int) K(int a, int b) => a < b ? (a, b) : (b, a);
  public float Get(int a, int b) => _rel.GetValueOrDefault(K(a, b)); }
public record Modifier(string Kind, float Value, int StartDay, int FadeDays);
public sealed class War { public int Id, A, B; public WarGoal Goal; public float WearA, WearB; public int StartDay; }
public sealed class Coalition { public List<int> Members = new(); public int NextCouncilDay; }

public enum TradeContext { Visit, CaravanAtGate, Meet, Radio, Route }
public sealed class TradeSession { public int A, B; public TradeContext Ctx;
  public List<ItemStack> OfferA = new(), OfferB = new(); }
public interface IValuation { float Worth(ItemStack s, Holdout to); string Why(ItemStack s, Holdout to); }
public sealed class Caravan : Party { public int OwnerId; public HexCoord? MeetTile; public int StayHours; }

public enum RadioKind { Station, MilitarySet, Relay, Tower }
public record RadioNode(int HoldoutId, HexCoord Tile, RadioKind Kind, int Range, bool Linked);
public sealed class Message { public int Id, From, To; public MessageKind Kind; public string PayloadJson; public int SentHour; }
public sealed class Envoy : Party { public int MessageId; public bool Returning; }

public sealed class Prisoner { public int SurvivorId, CaptorId; public int? JailBaseId; public int SinceDay; }
public record JailTierDef(string Id, int Capacity, int LockDifficulty, string ArtKey);
public sealed class AbandonedBase { public int BaseId, LeftDay, DeadInside; public int? SquatterBandId; }
public record RansomOffer(int GroupId, List<int> Captives, Dictionary<string, int> Price);

public enum NomadTier { Drifters, Looters, Survivalists, Preppers }
public sealed class Band : Holdout { public NomadTier Tier; public HexCoord? Camp; public int CampDaysLeft; public bool Outsider; }
public enum JobState { Offered, Active, Done, Failed, Void }
public sealed class PostedJob { public int Id, GroupId, DeadlineHour; public string Template; public JobState State; public string TargetJson; }
